var o="使用消息上的绘图按钮生成配图，也可在正文中使用 [img:tags]。";for(const t of document.querySelectorAll("[data-draw-usage]"))t.textContent=o;document.addEventListener("click",t=>{t.target.closest(".nav-item, .mobile-nav-item")&&window.scrollTo(0,0)});document.addEventListener("keydown",t=>{if(t.key!=="Enter"&&t.key!==" ")return;const e=t.target.closest(".nav-item, .mobile-nav-item");e&&(t.preventDefault(),e.click())});
